import sys

def main():
    input = sys.stdin.buffer.readline
    N = int(input())
    A = list(map(int, input().split()))

    NEG_INF = -10**30
    even = 0          # best sum with an even number of remaining elements
    odd = NEG_INF     # best sum with an odd number of remaining elements

    for i, a in enumerate(A, start=1):
        if i % 2 == 1:
            odd = max(odd, even + a)
        else:
            even = max(even, odd + a)

    print(odd if N % 2 == 1 else even)

if __name__ == "__main__":
    main()
